It is natural to ask whether a similar result holds in quasianalytic  situations, that is, when $ \varphi $ belongs to a quasianalytic local ring $ \mathcal{E}_{n+1}(M) $ (see the definition in Section \ref{udg}). However, the problem seems difficult to address in full generality. In Section \ref{uqac} of the present paper, we consider the particular case of quasianalytic polynomials in two variables, that is,
\begin{equation*}
\varphi(x,y)=y^d+a_1(x)y^{d-1}+\cdots+a_d(x)
\end{equation*}
where the coefficients $ a_j $ are function germs of one variable belonging to a given quasianalytic local ring $ \mathcal{E}_1(M) $. 
Despite its simplicity, this particular case is important, since in the analytic setting, Theorem \ref{classic} can be reduced to the same situation \emph{via} the preparation theorem and a potential-theoretic argument, so that the analyticity of smooth roots can then be obtained by elementary power series techniques (see e.g. Chapter V of \cite{Ba}). In the quasianalytic setting, power series expansions of germs are merely formal and cannot be used in the same way. We therefore combine an application of the Artin-type approximation property of Rotthaus \cite{Ro} together with a version of Puiseux's theorem for quasianalytic polynomials. This allows us, under a mild extra assumption, namely the stability of $ \mathcal{E}_1(M) $  under derivation, to show that if $ h $ is a germ of $ C^\infty $ function such that $ \varphi(x,h(x))=0 $, then $ h $ belongs to $ \mathcal{E}_1(M) $, as expected: this is the statement of Theorem \ref{main}. We then give an example showing that the result is generally false when $ \mathcal{E}_1(M) $ is non-quasianalytic.

\label{main} Assume that $ \mathcal{E}_1(M) $ is quasianalytic and stable under derivation, and
consider a polynomial 
\begin{equation*}
\varphi(x,y)=y^d+a_1(x)y^{d-1}+\cdots+a_d(x)
\end{equation*}
with $ a_j\in\mathcal{E}_1(M) $ for $ j=1,\ldots,d $. If $ h $ is a germ of $ C^\infty $ function at the origin in $ \mathbb{R} $ such that $ \varphi(x,h(x))=0 $, then $ h $ belongs to $ \mathcal{E}_1(M) $.

\label{thm.stablepointwiseprop}
Let $\M=(M_j)_j\in\RR_{>0}^{\NN_0}$ be a sequence with $M_0=1$ and $\alpha>0$. Consider the following statements:
\begin{itemize}
    \item[(i)] In case $\alpha\leq 2$, $\overline{\G}^{2-\alpha}\M$ is equivalent to an \hyperlink{lc}{$(\text{lc})$} sequence; if $\alpha>2$, there exists $\a'>\a$ such that $\overline{\G}^{2-\alpha'}\M$ is equivalent to an \hyperlink{lc}{$(\text{lc})$} sequence.
\item[(ii)] $\M$ satisfies \hyperlink{s-alg}{$(\on{alg})$}.
\item[(iii)] $\mathcal{\widetilde{A}}^{u}_{\{\M\}}(S_{\a})$ is an algebra.
\item[(iv)] There exists a characteristic function $f\in \mathcal{\widetilde{A}}^{u}_{\{\M\}} (S_\alpha)$, with  $f\sim^u_{\{\M\}} \sum_{j=0}^\infty c^f_j z^j$, such that $(|c^f_j|)_{j\in\NN_0}$ is equivalent to $\M$ and, moreover,  $c^f_j=(-1)^j|c^f_j|$ for all $j\in\NN_0$.
\end{itemize} 
Then, one has $(i)\Rightarrow(ii)\Rightarrow(iii)$, $(i)\Rightarrow(iv)$ and $(iii)+(iv)\Rightarrow(ii)$.

\label{main2} Let $ \gamma $ and $ r $ be positive real numbers. Assume that the sequence $ M $ is strongly regular, and
consider a polynomial 
\begin{equation*}
\varphi(z,w)=w^d+a_1(z)w^{d-1}+\cdots+a_d(z)
\end{equation*}
with $ a_j\in\mathcal{A}_M(S_{\gamma,r}) $ for $ j=1,\ldots,d $. If $ h $ is  an element of $ \mathcal{A}^\infty(S_{\gamma,r}) $ such that $ \varphi(z,h(z))=0 $ for $ z\in S_{\gamma,r} $, then $ h $ belongs to $ \mathcal{A}_M(S_{\gamma',r'}) $ for any $ \gamma'<\gamma $ and $ r'<r $.

\label{theorem1siddiqi}
	Let $\mathcal{M}=\{\M^{(p)}: p>0\}$ be a weight matrix (not necessarily \hyperlink{Msc}{$(\mathcal{M}_{\on{sc}})$}) and $0<\alpha\le 1$ be given such that $\lim_{j\rightarrow+\infty}(j^{(1-\alpha)j}M^{(p)}_j)^{1/j}=\infty$ for all $p>0$. Let $\mathcal{M}^{\alpha}=\{\M^{(p,\alpha)}: p>0\}$ be the matrix according to \eqref{ramiequ}. Then the following assertions are equivalent:
	\begin{itemize}
		\item[$(a)$] The matrix $\mathcal{M}^{\alpha}$ satisfies the property \hyperlink{R-rai}{$(\mathcal{M}_{\{\on{rai}\}})$}.

		\item[$(b)$] The class $\mathcal{A}_{\{\mathcal{M}\}}(S_{\alpha})$ is holomorphically closed.


		\item[$(c)$] The class $\mathcal{A}_{\{\mathcal{M}
			\}}(S_{\alpha})$ is inverse-closed.

	\end{itemize}
	If $\mathcal{M}$ has in addition \hyperlink{R-Comega}{$(\mathcal{M}_{\{\text{C}^{\omega}\}})$} and $\mathcal{M}^{\alpha}$ has \hyperlink{R-dc}{$(\mathcal{M}_{\{\on{dc}\}})$}, then the list of equivalences can be extended by

	\begin{itemize}
		\item[$(d)$] The class $\mathcal{A}_{\{\mathcal{M}\}}(S_{\alpha})$ is closed under composition.


		\item[$(e)$] The matrix $\mathcal{M}^{\alpha}$ satisfies the property \hyperlink{R-FdB}{$(\mathcal{M}_{\{\on{FdB}\}})$}.
	\end{itemize}

\label{theorem1siddiqi.}
	Let $\mathcal{M}=\{\M^{(p)}: p>0\}$ be a weight matrix and consider $\alpha> 1$. For each $p>0$, we suppose that there exists some $\alpha_p>\alpha$ such that $\overline{\G}^{1-\alpha_p}\M^{(p)}$ is equivalent to a (lc) sequence $\LL^{(p)}$ depending on $\alpha_p$. Then the following assertions are equivalent:
	\begin{itemize}
		\item[$(a)$] The matrix $\mathcal{M}$ satisfies the property \hyperlink{R-rai}{$(\mathcal{M}_{\{\on{rai}\}})$}.

		\item[$(b)$] The class $\mathcal{A}_{\{\mathcal{M}\}}(S_{\alpha})$ is holomorphically closed.


		\item[$(c)$] The class $\mathcal{A}_{\{\mathcal{M}
			\}}(S_{\alpha})$ is inverse-closed.

	\end{itemize}
	If $\mathcal{M}$ has in addition \hyperlink{R-Comega}{$(\mathcal{M}_{\{\text{C}^{\omega}\}})$} and \hyperlink{R-dc}{$(\mathcal{M}_{\{\on{dc}\}})$}, then the list of equivalences can be extended by

	\begin{itemize}
		\item[$(d)$] The class $\mathcal{A}_{\{\mathcal{M}\}}(S_{\alpha})$ is closed under composition.

		\item[$(e)$] The matrix $\mathcal{M}$ satisfies the property \hyperlink{R-FdB}{$(\mathcal{M}_{\{\on{FdB}\}})$}.
	\end{itemize}
